/* Typed access to fixtures/surfaces.json (generated by fixtures/gen.mjs from mcp-a2ui's golden output). */
import type { A2uiMessage } from '../src/a2ui/types';
import raw from './surfaces.json' with { type: 'json' };

interface Entry {
  fixture: string;
  title: string;
  messages: A2uiMessage[];
  sample: Record<string, unknown>;
}
export const SURFACES = raw as unknown as Record<string, Entry>;

/** A fresh copy of a fixture's createSurface message. */
export function createSurface(id: string): A2uiMessage {
  const entry = SURFACES[id];
  if (!entry) throw new Error(`no surface fixture ${id}`);
  return structuredClone(entry.messages[0]);
}

export const sampleOf = (id: string): Record<string, unknown> => SURFACES[id]?.sample ?? {};
